package com.bytbeat.mpctrainer

import android.content.Intent
import android.graphics.Color
import android.media.AudioAttributes
import android.media.AudioManager
import android.media.SoundPool
import android.media.ToneGenerator
import android.net.Uri
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.os.SystemClock
import android.provider.OpenableColumns
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.widget.*
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import kotlin.math.roundToLong

class TrainerActivity : AppCompatActivity() {
    data class PadSample(val soundId:Int,val name:String,val path:String)
    data class Event(val bank:Int,val pad:Int,val tick:Long,val track:Int,val velocity:Int)
    private lateinit var pool:SoundPool
    private val pads=Array(4){arrayOfNulls<PadSample>(16)}; private val events=mutableListOf<Event>(); private val mute=BooleanArray(4); private val padButtons=mutableListOf<Button>(); private val h=Handler(Looper.getMainLooper()); private val tone by lazy{ToneGenerator(AudioManager.STREAM_MUSIC,55)}
    private lateinit var status:TextView; private lateinit var learnCard:TextView; private lateinit var engine:LearnEngine
    private var bank=0;private var pad=0;private var track=0;private var bpm=90;private var tc=16;private var swing=50;private var playing=false;private var recording=false;private var overdub=false;private var noteRepeat=false;private var fullLevel=false;private var levels16=false;private var sourceBank=0;private var sourcePad=0;private var startMs=0L;private var learn=false;private var pending:Uri?=null;private var pendingName="";private var metronome=false;private var countIn=true;private var lastBeat=-1L
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);pool=SoundPool.Builder().setMaxStreams(24).setAudioAttributes(AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).build();restorePads();restoreProject();engine=LearnEngine(getSharedPreferences("mpc",MODE_PRIVATE).getInt("learn_engine_lesson",0));engine.begin(snapshot());setContentView(buildUi());refreshPads();refreshStatus()}
    private fun btn(label:String,click:()->Unit)=Button(this).apply{text=label;textSize=8.5f;setOnClickListener{click()}}
    private fun row(vararg v:View)=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;v.forEach{addView(it,LinearLayout.LayoutParams(0,48,1f))}}
    private fun buildUi():View{val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(10,8,10,8);setBackgroundColor(Color.rgb(216,210,195))};root.addView(TextView(this).apply{text="MPC TRAINER • LIVE III BASICS";textSize=16f;setTypeface(typeface,1);setTextColor(Color.rgb(38,37,33))});status=TextView(this).apply{setPadding(12,8,12,8);textSize=12f;setTextColor(Color.rgb(207,232,193));setBackgroundColor(Color.rgb(53,68,60))};root.addView(status,LinearLayout.LayoutParams(-1,72));learnCard=TextView(this).apply{setPadding(10,8,10,8);textSize=11f;setTextColor(Color.rgb(38,37,33));setBackgroundColor(Color.rgb(235,226,201));visibility=View.GONE};root.addView(learnCard)
        root.addView(row(btn("MAIN"){report("main");refreshStatus()},btn("BROWSE"){report("browse");browse()},btn("SAMPLE EDIT"){sampleEdit()},btn("LEARN"){learn=!learn;learnCard.visibility=if(learn)View.VISIBLE else View.GONE;if(learn){engine.begin(snapshot());showLesson()}}));root.addView(row(*Array(4){i->btn("BANK ${'A'+i}"){bank=i;refreshPads();refreshStatus()}}));val grid=GridLayout(this).apply{columnCount=4;rowCount=4};repeat(16){i->val b=Button(this).apply{textSize=8.5f;gravity=Gravity.CENTER;setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(58,57,53));setOnTouchListener{_,e->when(e.action){MotionEvent.ACTION_DOWN->{pad=i;hit(i,true);report("pad");if(noteRepeat)startRepeat()};MotionEvent.ACTION_UP,MotionEvent.ACTION_CANCEL->stopRepeat()};refreshPads();true}};padButtons+=b;grid.addView(b,GridLayout.LayoutParams().apply{width=0;height=80;columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(3,3,3,3)})};root.addView(grid,LinearLayout.LayoutParams(-1,0,1f));root.addView(row(btn("NOTE REPEAT"){noteRepeat=!noteRepeat;report("note_repeat");refreshStatus()},btn("FULL LEVEL"){fullLevel=!fullLevel;report("full_level");refreshStatus()},btn("16 LEVELS"){if(!levels16){sourceBank=bank;sourcePad=pad};levels16=!levels16;report("16_levels");refreshPads();refreshStatus()},btn("STEP SEQ"){steps()}));root.addView(row(btn("TC"){tc=when(tc){8->16;16->32;else->8};saveProject();report("tc");refreshStatus()},btn("SWING"){swing=when(swing){50->54;54->58;else->50};saveProject();report("swing");refreshStatus()},btn("TRACK −"){track=(track+3)%4;report("track");refreshStatus()},btn("TRACK +"){track=(track+1)%4;report("track");refreshStatus()}));root.addView(row(btn("METRO"){metronome=!metronome;saveProject();refreshStatus()},btn("COUNT IN"){countIn=!countIn;saveProject();refreshStatus()},btn("TRACK MUTE"){mute[track]=!mute[track];saveProject();report("track_mute");refreshStatus()},btn("SAVE"){saveProject();savePads();Toast.makeText(this,"Project saved",Toast.LENGTH_SHORT).show()}));root.addView(row(btn("REC"){record(false);report("record")},btn("OVERDUB"){record(true);report("overdub")},btn("STOP"){stopTransport()},btn("PLAY"){play()}));root.addView(row(btn("RESET LESSON"){engine.reset(snapshot());saveLesson();learn=true;learnCard.visibility=View.VISIBLE;showLesson()},btn("CONTROL GUIDE"){showControlGuide()}));return root}
    private fun snapshot()=LearnEngine.Snapshot(pads.sumOf{a->a.count{it!=null}},events.size,track,mute.count{it},tc,swing,noteRepeat,fullLevel,levels16)
    private fun report(a:String){if(!learn)return;val r=engine.report(a,snapshot());if(r.advanced){saveLesson();Toast.makeText(this,"Lesson complete",Toast.LENGTH_SHORT).show()};learnCard.text=if(r.advanced)engine.lessonCard() else "${engine.title()}\n${engine.explanation()}\n\n${r.message}"}
    private fun showLesson(){learnCard.text=engine.lessonCard()};private fun saveLesson(){getSharedPreferences("mpc",MODE_PRIVATE).edit().putInt("learn_engine_lesson",engine.lesson).apply()};private fun showControlGuide(){val n=MpcBasics.controls.map{it.name}.toTypedArray();AlertDialog.Builder(this).setTitle("CONTROL GUIDE").setItems(n){_,i->val c=MpcBasics.controls[i];AlertDialog.Builder(this).setTitle(c.name).setMessage("${c.purpose}\n\nPRACTICE • ${c.practice}").setPositiveButton("OK",null).show()}.show()}
    private fun velocity(i:Int)=if(levels16)(((i+1)*127f/16f).roundToLong().toInt()).coerceIn(1,127)else if(fullLevel)127 else 100
    private fun hit(i:Int,user:Boolean){val b=if(levels16)sourceBank else bank;val p=if(levels16)sourcePad else i;val v=velocity(i);pads[b][p]?.let{pool.play(it.soundId,v/127f,v/127f,1,0,1f)};if(user&&recording&&playing){events+=Event(b,p,quant(tick()),track,v);saveProject()};refreshStatus()}
    private fun loopTicks()=768L;private fun tick()=if(!playing)0L else(((SystemClock.elapsedRealtime()-startMs)/(60000.0/bpm/96.0)).toLong()%loopTicks());private fun quant(raw:Long):Long{val s=(384L/tc).coerceAtLeast(1);var q=(raw.toDouble()/s).roundToLong()*s;if((q/s)%2L==1L&&swing>50)q+=((s*(swing-50))/50.0).roundToLong();return q%loopTicks()}
    private val clock=object:Runnable{override fun run(){if(!playing)return;val t=tick();val beat=t/96;if(metronome&&beat!=lastBeat){lastBeat=beat;tone.startTone(if(beat%4==0L)ToneGenerator.TONE_PROP_BEEP2 else ToneGenerator.TONE_PROP_BEEP,45)};events.filter{!mute[it.track]&&distance(it.tick,t)<=1}.forEach{e->pads[e.bank][e.pad]?.let{val v=e.velocity.coerceIn(1,127)/127f;pool.play(it.soundId,v,v,1,0,1f)}};h.postDelayed(this,4)}}
    private fun distance(a:Long,b:Long):Long{val d=kotlin.math.abs(a-b);return minOf(d,loopTicks()-d)};private fun startClock(){lastBeat=-1;h.removeCallbacks(clock);h.post(clock)}
    private fun record(od:Boolean){if(playing)return;if(!od)events.removeAll{it.track==track};overdub=od;if(countIn){recording=false;playing=false;countDown(4){recording=true;playing=true;startMs=SystemClock.elapsedRealtime();startClock();refreshStatus()}}else{recording=true;playing=true;startMs=SystemClock.elapsedRealtime();startClock()};saveProject();refreshStatus()}
    private fun countDown(beats:Int,done:()->Unit){var left=beats;val gap=(60000L/bpm).coerceAtLeast(100);val r=object:Runnable{override fun run(){if(left<=0){done();return};status.text="COUNT IN • $left";tone.startTone(if(left==beats)ToneGenerator.TONE_PROP_BEEP2 else ToneGenerator.TONE_PROP_BEEP,55);left--;h.postDelayed(this,gap)}};h.post(r)};private fun play(){if(playing)return;recording=false;playing=true;startMs=SystemClock.elapsedRealtime();startClock();refreshStatus()};private fun stopTransport(){val od=overdub;playing=false;recording=false;overdub=false;h.removeCallbacks(clock);stopRepeat();report(if(od)"overdub_stop" else "stop");saveProject();refreshStatus()}
    private val repeater=object:Runnable{override fun run(){if(noteRepeat){hit(pad,true);h.postDelayed(this,(60000.0/bpm*(4.0/tc)).toLong().coerceAtLeast(25))}}};private fun startRepeat(){h.removeCallbacks(repeater);h.post(repeater)};private fun stopRepeat(){h.removeCallbacks(repeater)}
    private fun steps(){val box=GridLayout(this).apply{columnCount=4};val bs=ArrayList<Button>();repeat(16){val b=Button(this);bs+=b;box.addView(b,GridLayout.LayoutParams().apply{width=150;height=105})};fun redraw(){bs.forEachIndexed{i,b->val t=i*24L;val on=events.any{it.track==track&&it.bank==bank&&it.pad==pad&&it.tick==t};b.text="${i+1}\n${if(on)"●" else "○"}";b.setOnClickListener{val ix=events.indexOfFirst{it.track==track&&it.bank==bank&&it.pad==pad&&it.tick==t};if(ix>=0)events.removeAt(ix)else{events+=Event(bank,pad,t,track,127);report("step_added")};saveProject();redraw()}}};redraw();AlertDialog.Builder(this).setTitle("STEP SEQ • BAR 1").setView(box).setPositiveButton("DONE",null).show()}
    private fun browse(){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);type="audio/*"},901)}
    @Deprecated("Deprecated in Java")override fun onActivityResult(r:Int,c:Int,d:Intent?){super.onActivityResult(r,c,d);if(r!=901||c!=RESULT_OK)return;val u=d?.data?:return;pending=u;pendingName=name(u);val fd=contentResolver.openFileDescriptor(u,"r");val preview=if(fd!=null){val id=pool.load(fd.fileDescriptor,0,fd.statSize,1);fd.close();id}else 0;AlertDialog.Builder(this).setTitle("BROWSER • $pendingName").setMessage("Preview or load to BANK ${'A'+bank} PAD ${pad+1}.").setNegativeButton("CANCEL",null).setNeutralButton("PREVIEW"){_,_->if(preview!=0)pool.play(preview,.8f,.8f,1,0,1f)}.setPositiveButton("LOAD TO PAD"){_,_->loadPending()}.show()}
    private fun loadPending(){val u=pending?:return;val dir=File(filesDir,"samples").apply{mkdirs()};val f=File(dir,"${System.currentTimeMillis()}_${pendingName.replace(Regex("[^A-Za-z0-9._-]"),"_")}");contentResolver.openInputStream(u)?.use{input->FileOutputStream(f).use{input.copyTo(it)}};pads[bank][pad]=PadSample(pool.load(f.absolutePath,1),pendingName.substringBeforeLast('.'),f.absolutePath);savePads();refreshPads();report("loaded")}
    private fun sampleEdit(){val s=pads[bank][pad];if(s==null){Toast.makeText(this,"Load a WAV or MP3 to a pad first",Toast.LENGTH_SHORT).show();return};val src=File(s.path);status.text="SAMPLE EDIT • preparing ${s.name}…";Thread{try{val editable=AudioImport.toEditableWav(src,File(filesDir,"sample_edit/${src.nameWithoutExtension}_edit.wav"));WavSlicer.inspect(editable);runOnUiThread{showSampleEditor(editable,s.name)}}catch(e:Exception){runOnUiThread{status.text="SAMPLE EDIT • ${e.message}";Toast.makeText(this,"Sample Edit: ${e.message}",Toast.LENGTH_LONG).show()}}}.start()}
    private fun showSampleEditor(src:File,label:String){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,8,24,8)};val read=TextView(this);val start=SeekBar(this).apply{max=95;progress=0};val end=SeekBar(this).apply{max=100;progress=100};val pieces=SeekBar(this).apply{max=14;progress=6};fun update(){if(end.progress<=start.progress)end.progress=(start.progress+1).coerceAtMost(100);read.text="START ${start.progress}%   END ${end.progress}%\nCHOPS ${pieces.progress+2} • first slice → PAD ${pad+1}"};val l=object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,f:Boolean){update()};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){}};start.setOnSeekBarChangeListener(l);end.setOnSeekBarChangeListener(l);pieces.setOnSeekBarChangeListener(l);box.addView(TextView(this).apply{text="$label\nSet Start/End, then chop the selected range evenly across pads."});box.addView(read);box.addView(TextView(this).apply{text="START"});box.addView(start);box.addView(TextView(this).apply{text="END"});box.addView(end);box.addView(TextView(this).apply{text="NUMBER OF CHOPS"});box.addView(pieces);update();val dialog=AlertDialog.Builder(this).setTitle("SAMPLE EDIT").setView(box).setNegativeButton("CANCEL",null).setNeutralButton("PREVIEW",null).setPositiveButton("CHOP → PADS",null).create();dialog.setOnShowListener{dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener{Thread{try{val f=WavSlicer.slice(src,File(cacheDir,"sample_edit_preview.wav"),start.progress/100f,end.progress/100f);val id=pool.load(f.absolutePath,1);runOnUiThread{pool.setOnLoadCompleteListener{sp,sid,ok->if(ok==0&&sid==id)sp.play(id,.8f,.8f,1,0,1f)}}}catch(e:Exception){runOnUiThread{Toast.makeText(this,e.message,Toast.LENGTH_SHORT).show()}}}.start()};dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{val count=pieces.progress+2;val room=16-pad;if(count>room){Toast.makeText(this,"Only $room pad slots remain in this bank",Toast.LENGTH_SHORT).show();return@setOnClickListener};status.text="SAMPLE EDIT • chopping…";Thread{try{val out=File(filesDir,"samples/chops_${System.currentTimeMillis()}");val files=WavSlicer.chop(src,out,start.progress/100f,end.progress/100f,count,label.replace(Regex("[^A-Za-z0-9_-]"),"_"));runOnUiThread{files.forEachIndexed{i,f->val p=pad+i;pads[bank][p]=PadSample(pool.load(f.absolutePath,1),"${label.take(7)}_${i+1}",f.absolutePath)};savePads();refreshPads();status.text="SAMPLE EDIT • $count chops → BANK ${'A'+bank} PADS ${pad+1}-${pad+count}";Toast.makeText(this,"$count chops assigned to pads",Toast.LENGTH_SHORT).show();dialog.dismiss()}}catch(e:Exception){runOnUiThread{status.text="SAMPLE EDIT • ${e.message}";Toast.makeText(this,e.message,Toast.LENGTH_LONG).show()}}}.start()}};dialog.show()}
    private fun name(u:Uri):String{contentResolver.query(u,null,null,null,null)?.use{c->val i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0&&c.moveToFirst())return c.getString(i)};return"sample.wav"}
    private fun savePads(){val sp=getSharedPreferences("trainer_v2",MODE_PRIVATE).edit();for(b in 0..3)for(p in 0..15){val s=pads[b][p];if(s!=null){sp.putString("p_${b}_$p",s.path);sp.putString("n_${b}_$p",s.name)}};sp.apply()};private fun restorePads(){val sp=getSharedPreferences("trainer_v2",MODE_PRIVATE);for(b in 0..3)for(p in 0..15){val path=sp.getString("p_${b}_$p",null);if(path!=null&&File(path).exists())pads[b][p]=PadSample(pool.load(path,1),sp.getString("n_${b}_$p","sample")?:"sample",path)}}
    private fun saveProject(){val a=JSONArray();events.forEach{a.put(JSONObject().put("b",it.bank).put("p",it.pad).put("t",it.tick).put("tr",it.track).put("v",it.velocity))};val m=JSONArray();mute.forEach{m.put(it)};val o=JSONObject().put("events",a).put("bpm",bpm).put("tc",tc).put("swing",swing).put("mute",m).put("metro",metronome).put("countIn",countIn);getSharedPreferences("trainer_v2",MODE_PRIVATE).edit().putString("project",o.toString()).apply()};private fun restoreProject(){val raw=getSharedPreferences("trainer_v2",MODE_PRIVATE).getString("project",null)?:return;try{val o=JSONObject(raw);bpm=o.optInt("bpm",90);tc=o.optInt("tc",16);swing=o.optInt("swing",50);metronome=o.optBoolean("metro",false);countIn=o.optBoolean("countIn",true);val a=o.optJSONArray("events")?:JSONArray();for(i in 0 until a.length()){val x=a.getJSONObject(i);events+=Event(x.getInt("b"),x.getInt("p"),x.getLong("t"),x.getInt("tr"),x.optInt("v",100))};val m=o.optJSONArray("mute");if(m!=null)for(i in 0 until minOf(4,m.length()))mute[i]=m.optBoolean(i,false)}catch(_:Exception){}}
    private fun refreshPads(){padButtons.forEachIndexed{i,b->val s=if(levels16)pads[sourceBank][sourcePad]else pads[bank][i];b.text=if(levels16)"${i+1}\nVEL ${velocity(i)}"else"${i+1}\n${s?.name?.take(8)?:"EMPTY"}";b.alpha=if(i==pad)1f else .84f}};private fun refreshStatus(){status.text="SEQ 01 • TRACK ${track+1}${if(mute[track])" MUTE"else""} • BANK ${'A'+bank} • PAD ${pad+1}\n$bpm BPM • TC 1/$tc • SWING $swing% • MET ${if(metronome)"ON"else"OFF"} • COUNT ${if(countIn)"ON"else"OFF"}${if(recording)if(overdub)" • OVERDUB"else" • REC"else if(playing)" • PLAY"else""}"};override fun onDestroy(){h.removeCallbacksAndMessages(null);tone.release();pool.release();super.onDestroy()}
}
